def write(relative, source):
    path = ROOT / relative
    ast.parse(source)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(source, encoding="utf-8")
    print(f"записан {relative} ({len(source.splitlines())} строк)")


def patch(relative, replacements):
    path = ROOT / relative
    text = path.read_text(encoding="utf-8")
    changed = False
    for old, new in replacements:
        if old not in text:
            if new and new in text:
                continue                      # уже пропатчено
            raise SystemExit(f"В {relative} не найден фрагмент:\n{old[:150]}")
        text = text.replace(old, new, 1)
        changed = True
    if changed:
        ast.parse(text)
        path.write_text(text, encoding="utf-8")
        print(f"пропатчен {relative}")
    else:
        print(f"без изменений {relative}")


def fix_boris_line():
    path = ROOT / "data" / "npcs" / "npc_innkeeper_boris.json"
    text = path.read_text(encoding="utf-8")
    bad = "Ты всегда здесь желанны гость, друг. tonight кровать тёплая."
    good = "Ты всегда здесь желанный гость, друг. Кровать сегодня тёплая."
    if bad in text:
        path.write_text(text.replace(bad, good), encoding="utf-8")
        json.loads(path.read_text(encoding="utf-8"))
        print("исправлена битая ru-строка Бориса (friendly)")
    else:
        print("строка Бориса уже в порядке")


def main():
    write("engine/offline_npc.py", OFFLINE_PY)
    write("tests/test_offline_npc.py", TESTS_PY)
    patch("engine/controller.py", CONTROLLER_EDITS)
    patch("cli/app.py", CLI_EDITS)
    fix_boris_line()
    print("Готово. Проверка: pytest -q")


if __name__ == "__main__":
    main()